package dev.veltraph.client.garden.visitor.history;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Frame identity/ordering only; a constructed frame is not a token on an actual vanilla carrier. */
class VisitorHistoryNativeCallFrameTest {
 @Test void plainArgumentsCannotClaimDifferentActualInvocation(){var p=new Object();var a=new Object();var f=new VisitorHistoryNativeCallFrame(p,a,null,1);assertNull(f.claim(new Object(),a,null,1));assertNull(f.claim(p,new Object(),null,1));assertNull(f.claim(p,a,null,2));}
 @Test void claimIsOneShotAndOpaque(){var p=new Object();var f=new VisitorHistoryNativeCallFrame(p,null,Boolean.TRUE,0);var t=f.claim(p,null,Boolean.TRUE,0);assertNotNull(t);assertNull(f.claim(p,null,Boolean.TRUE,0));assertFalse(f.current(new Object(),p,null,Boolean.TRUE,0,false));}
 @Test void callerNormalBooleanCannotCompleteAnEntryFrame(){var p=new Object();var f=new VisitorHistoryNativeCallFrame(p,null,null,4);var t=f.claim(p,null,null,4);assertTrue(f.current(t,p,null,null,4,false));assertFalse(f.current(t,p,null,null,4,true));}
 @Test void actualNormalReturnEnablesOnlyExactCapturedInvocation(){var p=new Object();var a=new Object();var f=new VisitorHistoryNativeCallFrame(p,a,null,3);var t=f.claim(p,a,null,3);f.originalReturned(true);assertTrue(f.current(t,p,a,null,3,true));assertFalse(f.current(t,p,a,null,3,false));assertFalse(f.current(t,new Object(),a,null,3,true));}
 @Test void throwingOriginalCannotBecomeNormalAfterward(){var p=new Object();var f=new VisitorHistoryNativeCallFrame(p,null,null,5);var t=f.claim(p,null,null,5);f.originalReturned(false);f.originalReturned(true);assertFalse(f.current(t,p,null,null,5,true));assertFalse(f.current(t,p,null,null,5,false));}
 @Test void nestedTokenCannotCompleteOuterFrame(){var p=new Object();var o=new VisitorHistoryNativeCallFrame(p,null,null,4);var ot=o.claim(p,null,null,4);var n=new VisitorHistoryNativeCallFrame(p,null,null,4);var nt=n.claim(p,null,null,4);n.originalReturned(true);assertFalse(n.current(ot,p,null,null,4,true));assertFalse(o.current(nt,p,null,null,4,true));assertFalse(o.current(ot,p,null,null,4,true));o.originalReturned(true);assertTrue(o.current(ot,p,null,null,4,true));}
 @Test void crossThreadCannotClaimOrComplete()throws Exception{var p=new Object();var f=new VisitorHistoryNativeCallFrame(p,null,null,1);var t=f.claim(p,null,null,1);boolean[] result={true};var thread=new Thread(()->{result[0]=f.current(t,p,null,null,1,false);f.originalReturned(true);});thread.start();thread.join();assertFalse(result[0]);assertFalse(f.current(t,p,null,null,1,true));}
 @Test void listenerAndFlushIdentitiesAreExact(){var p=new Object();var callback=new Object();var f=new VisitorHistoryNativeCallFrame(p,callback,Boolean.FALSE,0);assertNull(f.claim(p,callback,Boolean.TRUE,0));var t=f.claim(p,callback,Boolean.FALSE,0);f.originalReturned(true);assertFalse(f.current(t,p,callback,Boolean.TRUE,0,true));assertTrue(f.current(t,p,callback,Boolean.FALSE,0,true));}
}
